<script setup>
import {computed,onMounted,ref} from 'vue';import{useRouter}from'vue-router';const router=useRouter(),items=ref([]),filtre=ref('Tous'),erreur=ref('');const statuts=computed(()=>['Tous',...new Set(items.value.map(i=>i.statut))]);const liste=computed(()=>filtre.value==='Tous'?items.value:items.value.filter(i=>i.statut===filtre.value));onMounted(async()=>{try{const r=await fetch('/api/candidatures');if(!r.ok)throw new Error();items.value=await r.json()}catch{erreur.value='Impossible de charger les candidatures.'}})
</script><template><main class="page"><h1>Candidatures</h1><nav><button v-for="s in statuts" :class="{actif:s===filtre}" @click="filtre=s">{{s}}</button></nav><p v-if="erreur">{{erreur}}</p><article v-for="c in liste" :key="c.id"><h2>{{c.prenom}} {{c.nom}}</h2><p>{{c.offre}} · {{c.email}}</p><span>{{c.statut}}</span><button v-if="c.statut==='preselectionne'" @click="router.push({name:'entretien-formulaire',params:{id:c.id}})">Créer l’entretien</button><button v-if="c.statut==='retenu'" @click="router.push({name:'contrat-fiche',params:{id:c.id}})">Générer le contrat</button></article></main></template><style scoped>.page{max-width:850px;margin:auto;padding:24px}nav{display:flex;gap:8px;flex-wrap:wrap}nav button,.page article button{border:1px solid #aaa;border-radius:8px;padding:8px;background:#fff}.actif{border-color:teal!important;color:teal}.page article{margin:14px 0;padding:16px;border:1px solid #ddd;border-radius:14px;background:#fff}.page article h2,.page article p{margin:0 0 8px}.page article button{display:block;margin:16px 0 0 auto;background:teal;color:#fff;border:0;font-weight:bold}</style>
